#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Every catalog SKU must appear, including SKUs with no movements that day
# (SKU-9 is in the catalog).
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) if (net[sku] != 0) print sku, net[sku] }' \
        movements.log
    printf 'SKU-9 0\n'
} | sort > stock.txt
